const {DatabaseSync}=require('node:sqlite');
const db=new DatabaseSync('/bench/home/work/.codegraph/codegraph.db');
function diag(qn,fp){
  const n=db.prepare('SELECT id,name FROM nodes WHERE qualified_name=? AND file_path=?').get(qn,fp);
  const files=db.prepare(\"SELECT DISTINCT s.file_path fp FROM edges e JOIN nodes s ON e.source=s.id WHERE e.target=? AND e.kind='calls'\").all(n.id);
  const tot=db.prepare(\"SELECT count(*) c FROM edges WHERE target=? AND kind='calls'\").get(n.id).c;
  console.log(qn+' @ '+fp+' -> total '+tot+', distinct src files '+files.length);
  console.log('  sample:', files.slice(0,6).map(x=>x.fp).join(', '));
}
